{
	"name": "design-system-react",
	"version": "0.10.65",
	"description": "Salesforce Lightning Design System for React",
	"license": "BSD-3-Clause",
	"engines": {
		"node": "14.x"
	},
	"scripts": {
		"build:docs": "babel-node ./scripts/build-docs.js",
		"build:design-tokens": "rm -r ./utilities/design-tokens/dist/* && cp -R ./node_modules/@salesforce-ux/design-system/design-tokens/dist/*.js ./utilities/design-tokens/dist/",
		"dist": "scripts/dist.sh",
		"build:npm-package": "npm run icons && npm run build:docs && npm run dist",
		"heroku-prebuild": "./scripts/heroku-prebuild.sh",
		"heroku-postbuild": "export NPM_CONFIG_PRODUCTION=true; export NODE_ENV=production; ./scripts/heroku-postbuild.sh",
		"icons": "babel-node scripts/inline-icons.js",
		"link": "./scripts/npm-link.sh",
		"lint": "concurrently \"npm:lint:style\" \"npm:lint:quality\"",
		"lint:docs": "prettylint \"*.md\"",
		"lint:fix": "cross-env NODE_ENV=test prettier --write \"**/*.{js,jsx}\" && prettylint \"*.json\" --fix && eslint --fix \"**/*.{js,jsx,json}\" --max-warnings=0",
		"lint:style": "concurrently \"prettier --list-different \"**/*.{js,jsx}\"\" \"prettylint \"*.json\"\"",
		"lint:quality": "eslint \"**/*.{jsx,js,json}\" --max-warnings=0",
		"npm:patch": "npm --no-git-tag-version version patch",
		"prepare-components": "node ./scripts/prepare-components.js",
		"publish:origin": "babel-node scripts/publish-to-git.js",
		"publish:edge": "babel-node scripts/publish-to-git.js --tag=edge",
		"publish:upstream": "babel-node scripts/publish-to-git.js --remote=upstream",
		"release:patch": "babel-node scripts/release.js --release=patch",
		"release:minor": "babel-node scripts/release.js --release=minor",
		"start": "concurrently -k --raw npm:start:storybook npm:start:browser-tests",
		"start:storybook": "start-storybook -p 9001 --ci -s ./node_modules",
		"start:browser-tests": "node tests/browser-tests-app",
		"static:start": "node app",
		"static:build": "build-storybook -o ./storybook",
		"test": "npm run prepare-components; npm run test:banner && concurrently \"npm:lint\" \"npm:test:unit\" \"npm:test:dom-snapshot\" \"npm:test:accessibility\" \"npm run build:docs && npm run test:docs\"",
		"test:banner": "node ./scripts/print-tests-top-banner.js",
		"test:docs": "babel-node ./tests/component-docs-test.js",
		"test:fix": "npm run lint:fix && npm run test",
		"test:unit": "cross-env NODE_ENV=mochatest karma start --single-run",
		"test:stories": "npm run test:dom-snapshot && npm run test:accessibility",
		"test:dom-snapshot": "cross-env NODE_ENV=test jest --runInBand --config=tests/story-based-tests.dom-snapshot-test.config.json",
		"test:image-snapshot": "cross-env NODE_ENV=test jest --runInBand --config=tests/story-based-tests.snapshot-test.config.json",
		"test:dom-snapshot:update": "cross-env NODE_ENV=test jest --updateSnapshot --config=tests/story-based-tests.dom-snapshot-test.config.json",
		"test:image-snapshot:update": "cross-env NODE_ENV=test npm run static:build && jest --updateSnapshot --config=tests/story-based-tests.snapshot-test.config.json",
		"test:accessibility": "npm run static:build && cross-env NODE_ENV=test PORT=8002 jest --runInBand --config=tests/story-based-tests.accessibility-test.config.json",
		"test:a11y": "npm run test:accessibility",
		"circle-ci": "cross-env NODE_ENV=test scripts/circle-ci.sh",
		"upload-diffs": "scripts/upload-diffs.sh",
		"validate": "npm ls",
		"version": "git add package.json && git commit -m \"Bump package version\""
	},
	"husky": {
		"hooks": {
			"pre-commit": "lint-staged"
		}
	},
	"lint-staged": {
		"*.{js,jsx}": [
			"prettier --write",
			"eslint --fix"
		]
	},
	"repository": {
		"type": "git",
		"url": "git+ssh://git@github.com/salesforce/design-system-react.git"
	},
	"jest": {
		"preset": "./tests/story-based-tests.dom-snapshot-test.config.json"
	},
