version = "0.9.0"
authors = ["Opral"]
edition = "2024"
description = "Embeddable version control for apps and AI agents."
license = "MIT"
homepage = "https://lix.dev"
repository = "https://github.com/opral/lix"
documentation = "https://docs.rs/lix-sdk"
readme = "README.md"
keywords = ["version-control", "ai-agents", "semantic-diff", "change-tracking", "embeddable"]
categories = ["development-tools", "artificial-intelligence", "filesystem"]
rust-version = "1.93"

[workspace.dependencies]
lix_cli = { path = "packages/cli", version = "0.9.0" }
lix_engine = { path = "packages/engine", version = "0.9.0" }
lix_local_filesystem = { path = "packages/local-filesystem", version = "0.9.0", default-features = false }
lix_rocksdb_storage = { path = "packages/rocksdb-storage", version = "0.9.0" }
lix_slatedb_storage = { path = "packages/slatedb-storage", version = "0.9.0" }
lix_sqlite_storage = { path = "packages/sqlite-storage", version = "0.9.0" }
lix_js_sdk = { path = "packages/js-sdk", version = "0.9.0" }
lix_order_key = { path = "plugins/order-key", version = "0.9.0" }
lix_plugin_api = { path = "packages/plugin-api", version = "0.9.0" }
lix_plugin_layout = { path = "packages/plugin-layout", version = "0.9.0" }
lix_plugin_wire = { path = "packages/plugin-wire", version = "0.9.0" }
lix_plugin_arena = { path = "packages/plugin-arena", version = "0.9.0" }
lix_sdk = { path = "packages/rs-sdk", version = "0.9.0" }
lix_server_protocol = { path = "packages/server-protocol", version = "0.9.0" }
mimalloc = { version = "0.1.52", features = ["local_dynamic_tls"] }

[workspace.lints.rust]
missing_copy_implementations = "warn"
missing_debug_implementations = "warn"
trivial_casts = "warn"
trivial_numeric_casts = "warn"
unexpected_cfgs = { level = "warn", check-cfg = [] }
unused_import_braces = "warn"
unused_qualifications = "warn"
# unused_crate_dependencies = "warn"

unconditional_recursion = "deny"

[workspace.lints.clippy]
# https://rust-lang.github.io/rust-clippy/master/index.html
all = { level = "warn", priority = -2 }
cargo = { level = "warn", priority = -1 }
complexity = { level = "allow", priority = -1 }
correctness = { level = "warn", priority = -1 }
nursery = { level = "allow", priority = -1 }
pedantic = { level = "allow", priority = -1 }
perf = { level = "warn", priority = -1 }
restriction = { level = "allow", priority = -1 }
style = { level = "allow", priority = -1 }
suspicious = { level = "warn", priority = -1 }

# Boxing hot-path batch/actor enum variants adds heap allocations, including
# per-file allocations, which is worse than their larger stack discriminants.
large_enum_variant = "allow"

# Cargo metadata/dependency topology is validated elsewhere in the release
# pipeline and does not describe runtime correctness or performance.
cargo_common_metadata = "allow"
redundant_feature_names = "allow"
multiple_crate_versions = "allow"

# Keep the published 0.2.0 surface local while the Markdown parser prepass
# optimization is evaluated. The vendored crate intentionally contains only
# its published library sources and licensing/readme material; remove this
# override once the equivalent upstream release is adopted.
[patch.crates-io]
markdown-syntax = { path = "vendor/markdown-syntax" }

[package]
name = "pbtc"
version = "0.1.0"
license = "GPL-3.0"
authors = ["Parity Technologies <admin@parity.io>"]
description = "Parity bitcoin client."

[dependencies]
log = "0.4"
env_logger = "0.5"
app_dirs = { git = "https://github.com/paritytech/app-dirs-rs" }
libc = "0.2"
clap = { version = "2", features = ["yaml"] }
chain = { path = "chain" }
keys = { path = "keys" }
message = { path = "message" }
network = { path = "network" }
miner = { path = "miner" }
p2p = { path = "p2p" }
script = { path = "script" }
storage = { path = "storage" }
db = { path = "db" }
verification = { path = "verification" }
sync = { path = "sync" }
import = { path = "import" }
logs = { path = "logs" }
rpc = { path = "rpc" }
primitives = { path = "primitives" }

[profile.dev]
debug = true
panic = 'abort'

[profile.release]
debug = true
panic = 'abort'

[profile.test]
debug = true

[[bin]]
path = "pbtc/main.rs"
name = "pbtc"

